def solve(mat):
    # Empty matrix determinant is defined as 1
    if not mat:
        return 1
    n = len(mat)
    # Ensure square matrix
    if any(len(row) != n for row in mat):
        raise ValueError('Matrix must be square')
    # Base cases
    if n == 1:
        return mat[0][0]
    if n == 2:
        return mat[0][0]*mat[1][1] - mat[0][1]*mat[1][0]
    det = 0
    for c in range(n):
        # Build minor matrix without first row and column c
        minor = [row[:c] + row[c+1:] for row in mat[1:]]
        cofactor = ((-1) ** c) * mat[0][c] * solve(minor)
        det += cofactor
    return det

