import random, math

def solve(mat):
    if not mat:
        return 1
    n = len(mat)
    for row in mat:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    a = [list(map(int, row)) for row in mat]
    det_sign = 1
    for k in range(n-1):
        # pivot
        if a[k][k] == 0:
            # find non-zero pivot in rows below
            swap = None
            for i in range(k+1, n):
                if a[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            a[k], a[swap] = a[swap], a[k]
            det_sign = -det_sign
        pivot = a[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                a[i][j] = (a[i][j]*pivot - a[i][k]*a[k][j]) // (a[k-1][k-1] if k>0 else 1)
        for i in range(k+1, n):
            a[i][k] = 0
    return det_sign * a[n-1][n-1]

def det_bruteforce(mat):
    # use recursion for small n
    n = len(mat)
    if n==0:
        return 1
    if n==1:
        return mat[0][0]
    if n==2:
        return mat[0][0]*mat[1][1]-mat[0][1]*mat[1][0]
    total=0
    for c in range(n):
        minor = [row[:c]+row[c+1:] for row in mat[1:]]
        total += ((-1)**c)*mat[0][c]*det_bruteforce(minor)
    return total

