def solve(coins, amount):
    """Return the minimum number of coins needed to make ``amount`` using
    unlimited supply of coin denominations in ``coins``. If impossible, return -1.
    ``coins`` is a list of positive integers, ``amount`` is a non‑negative integer.
    """
    # Edge cases
    if amount == 0:
        return 0
    if not coins:
        return -1
    # DP array where dp[i] = min coins for amount i, initialized to a large sentinel
    INF = amount + 1  # more than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= a:
                cand = dp[a - c] + 1
                if cand < best:
                    best = cand
        dp[a] = best
    return dp[amount] if dp[amount] != INF else -1

