    from fractions import Fraction
    n = len(matrix)
    if n == 0:
        return 1
    a = [[Fraction(val) for val in row] for row in matrix]
    sign = 1
    det = Fraction(1)
    for i in range(n):
        # find pivot
        pivot = i
        while pivot < n and a[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            a[i], a[pivot] = a[pivot], a[i]
            sign = -sign
        piv_val = a[i][i]
        det *= piv_val
        for r in range(i+1, n):
            factor = a[r][i] / piv_val
            for c in range(i, n):
                a[r][c] -= factor * a[i][c]
    det *= sign
    return det.numerator // det.denominator

