def solve(s: str) -> bool:
    """Check if brackets in the string are balanced.
    Considers (), [], {}. Ignores other characters.
    Returns True if every opening bracket has a matching closing bracket in correct order.
    """
    stack = []
    opening = set('([{')
    matching = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
        # ignore other characters
    return not stack

