def solve(matrix):
    n = len(matrix)
    if n == 0:
        return 1
    if n == 1:
        return matrix[0][0]
    # make a copy to avoid mutating input
    a = [row[:] for row in matrix]
    sign = 1
    for k in range(n - 1):
        # If pivot is zero, try to swap with a lower row
        if a[k][k] == 0:
            swap = None
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            a[k], a[swap] = a[swap], a[k]
            sign = -sign
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss update formula
                a[i][j] = a[i][j] * a[k][k] - a[i][k] * a[k][j]
                if k > 0:
                    # exact division guaranteed by Bareiss algorithm
                    a[i][j] //= a[k - 1][k - 1]
        # Zero out the column below the pivot to keep the matrix tidy
        for i in range(k + 1, n):
            a[i][k] = 0
    return sign * a[n - 1][n - 1]

