def solve(weights, values, capacity):
    # 0/1 knapsack using DP, handling zero-weight items correctly
    dp = [0] * (capacity + 1)
    for w, v in zip(weights, values):
        if w == 0:
            # Zero-weight item can be added to any capacity exactly once
            for c in range(capacity, -1, -1):
                dp[c] += v
            continue
        if w > capacity:
