def solve(matrix):
    """Return the determinant of a square integer matrix.
    Implements the Bareiss fraction‑free algorithm, which yields an exact integer
    result without intermediate fractions. Handles empty matrix (determinant 1).
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square matrix
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Make a mutable copy of the matrix
    A = [list(map(int, row)) for row in matrix]
    sign = 1  # track sign changes from row swaps
    for k in range(n - 1):
        # Ensure a non‑zero pivot; if zero, try to swap with a lower row
        if A[k][k] == 0:
            swap = None
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0  # singular matrix
            A[k], A[swap] = A[swap], A[k]
            sign = -sign
        pivot = A[k][k]
        prev_pivot = A[k - 1][k - 1] if k > 0 else 1
        # If previous pivot is zero, determinant is zero
        if prev_pivot == 0:
            return 0
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss update formula: (a_ij * pivot - a_ik * a_kj) // prev_pivot
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev_pivot
        # Zero out the column below the pivot (optional for clarity)
        for i in range(k + 1, n):
            A[i][k] = 0
    return sign * A[n - 1][n - 1]

