def solve(weights, values, capacity):
    """0/1 knapsack returning max total value for weight <= capacity.
    Handles zero-weight items by adding their positive values once.
    Optimizes DP size to min(capacity, sum of positive weights)."""
    total_zero = 0
    items = []
    total_pos_weight = 0
    for w, v in zip(weights, values):
        if w == 0:
            if v > 0:
                total_zero += v
            continue
        if w < 0:
            # negative weight not expected; ignore
            continue
        items.append((w, v))
        total_pos_weight += w
    # effective capacity cannot exceed total weight of all items
    eff_cap = min(capacity, total_pos_weight)
    dp = [0] * (eff_cap + 1)
    for w, v in items:
        if w > eff_cap:
            # item too heavy for effective capacity, skip
            continue
        for c in range(eff_cap, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    best = max(dp)  # best value for weight <= eff_cap
    return best + total_zero

