def solve(words, k):
    """Return the k most frequent words from *words*.
    Words are ordered by decreasing frequency; ties are broken alphabetically.
    If the k-th frequency is shared by additional words, all those words are included.
    """
    if k <= 0:
        return []
    from collections import Counter
    cnt = Counter(words)
    # sort by (-freq, word)
    sorted_items = sorted(cnt.items(), key=lambda x: (-x[1], x[0]))
    result = []
    last_freq = None
    for word, freq in sorted_items:
        if len(result) < k:
            result.append(word)
            last_freq = freq
        else:
            if freq == last_freq:
                result.append(word)
            else:
                break
    return result

