def solve(matrix):
    """Return the determinant of a square integer matrix.
    Uses the Bareiss fraction‑free algorithm for exact integer arithmetic.
    An empty matrix (no rows) or a matrix with empty rows is defined to have
    determinant 1.
    """
    # Handle empty matrix or matrix with empty rows
    if not matrix or not any(matrix):
        return 1
    n = len(matrix)
    # Verify that each row has length n; if a row is empty, treat as empty matrix
    for row in matrix:
        if len(row) != n:
            # If rows are empty, treat as empty matrix per spec
            if len(row) == 0:
                return 1
            raise ValueError('Matrix must be square')
    # Make a mutable copy of the matrix elements as ints
    A = [list(map(int, row)) for row in matrix]
    sign = 1  # track sign changes from row swaps
    for k in range(n - 1):
        # Ensure a non‑zero pivot; if zero, try to swap with a lower row
        if A[k][k] == 0:
            swap = None
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0  # singular matrix
            A[k], A[swap] = A[swap], A[k]
            sign = -sign
        pivot = A[k][k]
        prev = A[k - 1][k - 1] if k > 0 else 1
        # Perform Bareiss update on the sub‑matrix
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev
        # Zero out the column below the pivot (optional)
        for i in range(k + 1, n):
            A[i][k] = 0
    return sign * A[n - 1][n - 1]

