    """Return the determinant of a square integer matrix.
    Uses the Bareiss fraction‑free algorithm for exact integer results.
    An empty matrix (no rows) or a matrix consisting solely of empty rows
    is defined to have determinant 1.
    """
    # Empty matrix cases
    if not matrix:
        return 1
    # If every row is empty, treat as empty matrix per specification
    if all(len(row) == 0 for row in matrix):
        return 1
    n = len(matrix)
    # Verify square dimensions (non‑empty rows must all have length n)
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Make a mutable copy of the matrix as ints
    A = [list(map(int, row)) for row in matrix]
    sign = 1  # sign changes from row swaps
    for k in range(n - 1):
        # Ensure a non‑zero pivot; if zero, try to swap with a lower row
        if A[k][k] == 0:
            swap = None
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0  # singular matrix
            A[k], A[swap] = A[swap], A[k]
            sign = -sign
        pivot = A[k][k]
        prev = A[k - 1][k - 1] if k > 0 else 1
        # Bareiss update on the sub‑matrix
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev
        # Optional: zero out the column below the pivot for clarity
        for i in range(k + 1, n):
            A[i][k] = 0
    return sign * A[n - 1][n - 1]

