def solve(n, edges):
    from heapq import heappush, heappop
    adj=[[] for _ in range(n)]
    indeg=[0]*n
    seen=set()
    for a,b in edges:
        if (a,b) in seen:
            continue
        seen.add((a,b))
        adj[a].append(b)
        indeg[b]+=1
    for lst in adj:
        lst.sort()
    heap=[]
    for i in range(n):
        if indeg[i]==0:
            heappush(heap,i)
    order=[]
    while heap:
        u=heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v]-=1
            if indeg[v]==0:
                heappush(heap,v)
    return order if len(order)==n else []

