import random, sys
def det_brut(m):
    n=len(m)
    if n==0:
        return 1
    if n==1:
        return m[0][0]
    res=0
    for c in range(n):
        sub=[[m[i][j] for j in range(n) if j!=c] for i in range(1,n)]
