def det_brut(m):
    n=len(m)
    if n==0:
        return 1
    if n==1:
        return m[0][0]
    res=0
    for c in range(n):
        sub=[[m[i][j] for j in range(n) if j!=c] for i in range(1,n)]
        sign = -1 if c%2 else 1
        res+=sign*m[0][c]*det_brut(sub)
    return res
for n in range(0,7):
    for _ in range(200):
        mat=[[random.randint(-10,10) for _ in range(n)] for __ in range(n)]
        a=solve(mat)
        b=det_brut(mat)
        if a!=b:
