def solve(matrix):
    """Return the determinant of a square integer matrix.
    An empty matrix (or matrix with no rows) has determinant 1.
    The implementation uses the Bareiss algorithm for exact integer arithmetic.
    """
    # Handle empty matrix (e.g., [] or [[]])
    if not matrix or not matrix[0]:
        return 1
    n = len(matrix)
    # Verify square matrix
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Deep copy to avoid mutating the input
    a = [list(row) for row in matrix]
    det_sign = 1
    for k in range(n - 1):
        # Find a non‑zero pivot in column k at or below row k
        pivot_row = None
        for i in range(k, n):
            if a[i][k] != 0:
                pivot_row = i
                break
        if pivot_row is None:
            return 0
        if pivot_row != k:
            a[k], a[pivot_row] = a[pivot_row], a[k]
            det_sign = -det_sign
        pivot = a[k][k]
        prev_pivot = a[k-1][k-1] if k > 0 else 1
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss update keeps values integral
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // prev_pivot
            a[i][k] = 0
    return det_sign * a[n-1][n-1]

