def solve(weights, values, capacity):
    """0/1 knapsack: maximum total value for total weight <= capacity.
    Handles zero-weight items by adding their positive values once.
    """
    if capacity < 0:
        return 0
    # Sum of positive values of zero-weight items (can always be taken)
    zero_sum = 0
    items = []
    for w, v in zip(weights, values):
        if w == 0:
            if v > 0:
                zero_sum += v
            # ignore zero-weight items with non‑positive value
        elif w > 0:
            items.append((w, v))
        # negative weights are unexpected and ignored
    dp = [0] * (capacity + 1)
    for w, v in items:
        if w > capacity:
            continue
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    # best value for any weight up to capacity
    best = max(dp) if dp else 0
    return best + zero_sum

