def solve(n):
    """Return the number of prime numbers strictly less than n.
    Implements the classic Sieve of Eratosthenes.
    """
    if n <= 2:
        return 0
    # Boolean list where index represents the number
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    import math
    limit = int(math.isqrt(n - 1))
    for p in range(2, limit + 1):
        if is_prime[p]:
            start = p * p
            step = p
            for multiple in range(start, n, step):
                is_prime[multiple] = False
    return sum(is_prime)

