def solve(lst):
    """Flatten a nested list of integers into a flat list preserving order.
    Handles arbitrarily deep nesting without recursion limits.
    """
    result = []
    stack = [lst]
    while stack:
        item = stack.pop()
        if isinstance(item, list):
            # push elements in reverse to process left-to-right
            for sub in reversed(item):
                stack.append(sub)
        else:
            result.append(item)
    return result

