def solve(matrix):
    """Return the determinant of a square integer matrix.
    Uses the Bareiss fraction‑free algorithm for exact integer arithmetic.
    An empty matrix (no rows) or a matrix consisting solely of empty rows
    (e.g., [[]] or [[], []]) has determinant 1.
    """
    # Handle empty matrix or matrix with only empty rows
    if not matrix or all(len(row) == 0 for row in matrix):
        return 1
    n = len(matrix)
    # Verify square dimensions (non‑empty rows must all have length n)
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Make mutable copy as integers
    A = [list(map(int, row)) for row in matrix]
    sign = 1
    for k in range(n - 1):
        # Pivot selection and row swap if needed
        if A[k][k] == 0:
            swap = None
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0  # singular matrix
            A[k], A[swap] = A[swap], A[k]
            sign = -sign
        pivot = A[k][k]
        prev = A[k - 1][k - 1] if k > 0 else 1
        # Bareiss update on the sub‑matrix
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev
        # Zero out the column below the pivot (optional)
        for i in range(k + 1, n):
            A[i][k] = 0
    return sign * A[n - 1][n - 1]

