def solve(strs):
    from collections import defaultdict
    groups = defaultdict(list)
    for s in strs:
        key = ''.join(sorted(s))
        groups[key].append(s)
    for grp in groups.values():
        grp.sort()
    return sorted(groups.values(), key=lambda g: (g[0] if g else '', g))

